import{_ as t,o,c as a,a5 as i}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"FR 3.9.6 — Set Credit","description":"","frontmatter":{},"headers":[],"relativePath":"feature/srs/08-subscription-billing/3-9-6-set-credit/spec.md","filePath":"feature/srs/08-subscription-billing/3-9-6-set-credit/spec.md"}'),r={name:"feature/srs/08-subscription-billing/3-9-6-set-credit/spec.md"};function c(d,e,n,s,l,p){return o(),a("div",null,[...e[0]||(e[0]=[i('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Domain Index</a> · <strong>Spec</strong> · <a href="./plan.html">Plan</a> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="fr-3-9-6-—-set-credit" tabindex="-1">FR 3.9.6 — Set Credit <a class="header-anchor" href="#fr-3-9-6-—-set-credit" aria-label="Permalink to &quot;FR 3.9.6 — Set Credit&quot;">​</a></h1><table tabindex="0"><thead><tr><th style="text-align:left;">Field</th><th style="text-align:left;">Value</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>FR Code</strong></td><td style="text-align:left;"><code>3.9.6</code></td></tr><tr><td style="text-align:left;"><strong>Use Case ID</strong></td><td style="text-align:left;"><code>UC-127</code></td></tr><tr><td style="text-align:left;"><strong>Feature</strong></td><td style="text-align:left;">Set Credit</td></tr><tr><td style="text-align:left;"><strong>Domain</strong></td><td style="text-align:left;">Subscription &amp; Billing (<code>3.9</code>)</td></tr><tr><td style="text-align:left;"><strong>Canonical Actors / Roles</strong></td><td style="text-align:left;"><code>Owner</code></td></tr><tr><td style="text-align:left;"><strong>Business Rules</strong></td><td style="text-align:left;"><code>BR-20, BR-65</code></td></tr><tr><td style="text-align:left;"><strong>Message Codes</strong></td><td style="text-align:left;"><code>MSG01, MSG02, MSG03, MSG07, MSG53</code></td></tr><tr><td style="text-align:left;"><strong>Status</strong></td><td style="text-align:left;">Implemented — Production Verified (Consolidates <code>workspace-credit-unification</code> &amp; <code>member-credit</code> (<code>WorkspaceCreditController</code> + retired personal-limit <code>410</code> compatibility))</td></tr></tbody></table><h2 id="_1-objective-business-value" tabindex="-1">1. Objective &amp; Business Value <a class="header-anchor" href="#_1-objective-business-value" aria-label="Permalink to &quot;1. Objective &amp; Business Value&quot;">​</a></h2><p>Allow an Agency <code>Owner</code> to configure per-Workspace AI Credit spending ceilings (<code>PUT /api/v1/agencies/{agencyId}/credit/workspaces/{workspaceId}/limit</code>) with optimistic concurrency (<code>expectedRevision</code>), governing how much of the shared Agency wallet each Workspace (<code>Owner</code>, <code>Manager</code>, <code>Creator</code>) may consume per billing period.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>As an authorized <code>Owner</code>, I want to execute <strong>Set Credit</strong> with strong ACID financial/administrative guarantees, deterministic concurrency protection, and complete audit logging so that BrandHub&#39;s operations strictly satisfy <code>BR-20, BR-65</code> without manual database intervention.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ol><li><strong>Canonical Role &amp; Tenant Security:</strong> Server-side authorization enforces <code>Owner</code> on every request (<code>Admin</code> verified against live DB <code>user_system_roles</code>; <code>Owner</code>/<code>Manager</code>/<code>Creator</code> verified against live <code>agencies</code> / <code>workspace_members</code>). Unauthorized callers receive <code>403 FORBIDDEN</code> (<code>MSG07</code>) or scoped <code>404 NOT_FOUND</code> on IDOR probes.</li><li><strong>Core Domain &amp; Financial Invariants:</strong></li></ol><ul><li><strong>1. Semantic Distinction of <code>NULL</code> vs <code>0</code> (<code>BR-65</code>):</strong> <code>cap = null</code> explicitly removes the separate Workspace ceiling (Workspace may spend up to the shared Agency wallet); <code>cap = 0</code> explicitly blocks all positive-cost AI generations in that Workspace; blank UI inputs are never coerced to <code>0</code>.</li><li><strong>2. Overlapping Ceiling Model &amp; Non-Retroactivity:</strong> Workspace caps are spending ceilings (not pre-allocated sub-wallets), so the sum of caps across Workspaces may exceed the Agency balance. Lowering a Workspace cap immediately gates new reservations without rewriting historical <code>SETTLED</code> usage or cancelling in-flight <code>RESERVED</code> jobs.</li><li><strong>3. Optimistic Revision Guard:</strong> Missing <code>workspace_credit_limits</code> row starts at <code>revision = 0</code>; updates verify <code>expectedRevision</code> under the parent Agency row lock and increment <code>revision</code> (<code>409 CONFLICT</code> on stale concurrent save).</li></ul><ol start="3"><li><strong>Auditability &amp; Idempotency:</strong> Every mutation records correlation <code>requestId</code> and structured audit evidence (<code>audit_logs</code> / <code>billing_audit_events</code> / <code>admin_account_operations</code>), and supports safe retry without duplicate financial side effects.</li><li><strong>Internationalization (<code>vi.json</code> + <code>en.json</code>):</strong> All headings, table columns, status pills, dialogs, validation hints, and error banners use key-parallel translations (<code>credit.workspace.{title,unlimited,zeroBlocked,saveCap,staleConflict}</code> in <code>src/i18n/locales/{vi,en}/credit.json</code>) on <code>brandhub-web</code> and <code>tr()</code> on <code>brandhub-mobile-app</code> — zero hardcoded Vietnamese or English text in JSX/TSX.</li><li><strong>Light &amp; Dark Mode Compliance:</strong> All components (<code>pages/credit/components/WorkspaceCreditPanel.tsx</code>, <code>WorkspaceCreditRow.tsx</code>, <code>WorkspaceCreditForm.tsx</code>, <code>CreditAmountForm.tsx</code> on Web and <code>src/screens/billing/AgencyCreditScreen.tsx</code> (<code>Owner</code> Workspace cap editor) on Mobile) use semantic CSS variables / Tailwind <code>dark:</code> variants and <code>useAppPreferences().palette</code> tokens with WCAG AA contrast across Light and Dark modes.</li></ol><h2 id="_4-ui-ux-screen-states" tabindex="-1">4. UI / UX &amp; Screen States <a class="header-anchor" href="#_4-ui-ux-screen-states" aria-label="Permalink to &quot;4. UI / UX &amp; Screen States&quot;">​</a></h2><ul><li><strong>Web Surfaces (<code>brandhub-web</code>):</strong> <code>pages/credit/components/WorkspaceCreditPanel.tsx</code>, <code>WorkspaceCreditRow.tsx</code>, <code>WorkspaceCreditForm.tsx</code>, <code>CreditAmountForm.tsx</code></li><li><strong>Mobile Surfaces (<code>brandhub-mobile-app</code>):</strong> <code>src/screens/billing/AgencyCreditScreen.tsx</code> (<code>Owner</code> Workspace cap editor)</li><li><strong>UI States:</strong><ul><li><strong>Loading / Busy:</strong> Skeleton placeholders on initial query; disabled submit button + spinner during in-flight mutation to prevent double-submit races.</li><li><strong>Empty:</strong> Contextual localized empty state (e.g. zero invoices/moderation items/users matching filter) with zero fabricated mock data.</li><li><strong>Success:</strong> Scoped <code>TanStack Query</code> cache invalidation, updated KPI/row state, and localized confirmation toast.</li><li><strong>Conflict / Error:</strong> Explicit <code>409</code> stale-revision reload prompt or localized validation banner preserving user draft inputs.</li></ul></li></ul><h2 id="_5-api-contract" tabindex="-1">5. API Contract <a class="header-anchor" href="#_5-api-contract" aria-label="Permalink to &quot;5. API Contract&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Method &amp; Endpoint</th><th style="text-align:left;">Auth / Guard</th><th style="text-align:left;">Controller &amp; Service Handler</th></tr></thead><tbody><tr><td style="text-align:left;"><code>GET /api/v1/agencies/{agencyId}/credit/workspaces</code></td><td style="text-align:left;">Bearer (<code>Owner, Manager, Creator</code>)</td><td style="text-align:left;"><code>WorkspaceCreditController.list()</code> -&gt; returns Workspace caps, current <code>revision</code>, <code>workspaceUsed</code>, and <code>workspaceHeld</code></td></tr><tr><td style="text-align:left;"><code>PUT /api/v1/agencies/{agencyId}/credit/workspaces/{workspaceId}/limit</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>WorkspaceCreditController.update()</code> -&gt; sets `{ cap: number</td></tr><tr><td style="text-align:left;"><code>PUT /api/v1/agencies/{agencyId}/credit/policy &amp; /members/{memberId}/limit</code></td><td style="text-align:left;">Bearer (<code>Owner</code>)</td><td style="text-align:left;"><code>AgencyCreditConfigurationController</code> -&gt; returns <code>410 CREDIT_PERSONAL_LIMIT_RETIRED</code> on deprecated personal-limit writes per Workspace Credit Unification</td></tr></tbody></table><h2 id="_6-error-handling-edge-cases" tabindex="-1">6. Error Handling &amp; Edge Cases <a class="header-anchor" href="#_6-error-handling-edge-cases" aria-label="Permalink to &quot;6. Error Handling &amp; Edge Cases&quot;">​</a></h2><ul><li><code>FORBIDDEN</code> (<code>403</code>, <code>MSG07</code>): Caller lacks <code>Owner</code> permission or attempts cross-Agency/cross-Workspace access.</li><li><code>CONFLICT</code> (<code>409</code>, <code>MSG03</code>): Stale <code>expectedRevision</code> / <code>rowVersion</code>, duplicate idempotency key with mutated payload, or prohibited self-sanction/last-Admin demotion.</li><li><code>BAD_REQUEST</code> / <code>PAYLOAD_TOO_LARGE</code> (<code>400</code> / <code>413</code>, <code>MSG02</code> / <code>MSG14</code>): Invalid date range, negative/unsafe integer amount, malformed CSV, or de-scoped operation (e.g., plan downgrade or non-SePay provider).</li></ul><h2 id="_7-related-specifications-references" tabindex="-1">7. Related Specifications &amp; References <a class="header-anchor" href="#_7-related-specifications-references" aria-label="Permalink to &quot;7. Related Specifications &amp; References&quot;">​</a></h2><ul><li><strong>Related SRS FRs &amp; Modules:</strong> <a href="./../3-9-4-view-ai-credit-tracking/spec.html">FR 3.9.4 — View AI Credit Tracking</a> · <a href="./../3-9-5-buy-credit/spec.html">FR 3.9.5 — Buy Credit</a></li><li><strong>BA Domain Baseline:</strong> <a href="./../../../../ba/08-subscription-billing.html">BA Specification</a> · <a href="./../../../../ba/10-roles-permissions-matrix.html">Roles &amp; Permissions Matrix</a></li></ul><h2 id="_8-definition-of-done-out-of-scope" tabindex="-1">8. Definition of Done &amp; Out of Scope <a class="header-anchor" href="#_8-definition-of-done-out-of-scope" aria-label="Permalink to &quot;8. Definition of Done &amp; Out of Scope&quot;">​</a></h2><ul><li><strong>Definition of Done:</strong> Verified via JUnit 5 + isolated PostgreSQL/MongoDB integration tests, TypeScript/Playwright Web checks, Jest Mobile tests, <code>vi.json</code>/<code>en.json</code> key parity, and Light/Dark theme audit (<a href="./test.html">test.md</a>).</li><li><strong>Out of Scope:</strong> De-scoped capabilities (subscription plan downgrade, PayOS/VNPay/Stripe gateways, or copyright/plagiarism moderation).</li></ul>',21)])])}const m=t(r,[["render",c]]);export{u as __pageData,m as default};
